// IssuerBackendServiceHandler is an implementation of the vca.backend.v1.IssuerBackendService
// service.
type IssuerBackendServiceHandler interface {
	// RegisterCredentialConfiguration makes a published schema known to the
	// DPG so the DPG can issue it (ADR-013 decision 3).
	RegisterCredentialConfiguration(context.Context, *connect.Request[v1.RegisterCredentialConfigurationRequest]) (*connect.Response[v1.RegisterCredentialConfigurationResponse], error)
	// CreateOffer builds an OID4VCI credential offer for one subject.
	CreateOffer(context.Context, *connect.Request[v1.CreateOfferRequest]) (*connect.Response[v1.CreateOfferResponse], error)
	// Issue produces one credential and returns it as opaque bytes.
	Issue(context.Context, *connect.Request[v1.IssueRequest]) (*connect.Response[v1.IssueResponse], error)
	// IssueBatch produces many credentials in one call.
	IssueBatch(context.Context, *connect.Request[v1.IssueBatchRequest]) (*connect.Response[v1.IssueBatchResponse], error)
	// GetIssuanceStatus returns the state of one offer or deferred issuance.
	GetIssuanceStatus(context.Context, *connect.Request[v1.GetIssuanceStatusRequest]) (*connect.Response[v1.GetIssuanceStatusResponse], error)
	// Revoke sets the status bit of one credential through its status index.
	Revoke(context.Context, *connect.Request[v1.RevokeRequest]) (*connect.Response[v1.RevokeResponse], error)
	// ListIssuedCredentials searches the ledger of issued credentials that
	// the DPG keeps. An adapter serves it only when it lists
	// FEATURE_ISSUED_LEDGER.
	ListIssuedCredentials(context.Context, *connect.Request[v1.ListIssuedCredentialsRequest]) (*connect.Response[v1.ListIssuedCredentialsResponse], error)
	// GetIssuerMetadata returns the OID4VCI issuer metadata of the DPG.
	GetIssuerMetadata(context.Context, *connect.Request[v1.GetIssuerMetadataRequest]) (*connect.Response[v1.GetIssuerMetadataResponse], error)
	// GetIssuerIdentity returns the identifiers, the key, and the metadata
	// the DPG signs with. An empty answer means the DPG has no identity
	// yet (ADR-046 decision 1).
	GetIssuerIdentity(context.Context, *connect.Request[v1.GetIssuerIdentityRequest]) (*connect.Response[v1.GetIssuerIdentityResponse], error)
	// ProvisionIssuerIdentity asks the DPG to make a key and an identifier
	// in one step. The DPG keeps the key (ADR-046 decision 2). An adapter
	// serves it only when it lists FEATURE_ISSUER_IDENTITY_PROVISION.
	ProvisionIssuerIdentity(context.Context, *connect.Request[v1.ProvisionIssuerIdentityRequest]) (*connect.Response[v1.ProvisionIssuerIdentityResponse], error)
	// ImportIssuerIdentity binds an existing DID or X.509 chain to a key in
	// the key store of the DPG (ADR-046 decision 2). An adapter serves it
	// only when it lists FEATURE_ISSUER_IDENTITY_IMPORT_DID or
	// FEATURE_ISSUER_IDENTITY_IMPORT_X509.
	ImportIssuerIdentity(context.Context, *connect.Request[v1.ImportIssuerIdentityRequest]) (*connect.Response[v1.ImportIssuerIdentityResponse], error)
	// SetPresentationRequirement names the credential a holder presents
	// before the DPG issues (ADR-051 decision 6). An adapter serves it only
	// when it lists FEATURE_PRESENTATION_DURING_ISSUANCE.
	SetPresentationRequirement(context.Context, *connect.Request[v1.SetPresentationRequirementRequest]) (*connect.Response[v1.SetPresentationRequirementResponse], error)
	// GetPresentationRequirement returns the credential a holder presents
	// before the DPG issues, as the issuer set it. An adapter serves it
	// only when it lists FEATURE_PRESENTATION_DURING_ISSUANCE.
	GetPresentationRequirement(context.Context, *connect.Request[v1.GetPresentationRequirementRequest]) (*connect.Response[v1.GetPresentationRequirementResponse], error)
	// GetHolderSignInSource returns the data source of a credential that a
	// holder claims after a sign in, with no offer. The source finds the
	// subject (ADR-052 decision 3). An adapter serves it only when it
	// lists FEATURE_HOLDER_SIGN_IN_SOURCE.
	GetHolderSignInSource(context.Context, *connect.Request[v1.GetHolderSignInSourceRequest]) (*connect.Response[v1.GetHolderSignInSourceResponse], error)
	// SetHolderSignInSource stores that data source for the credential
	// configurations of one schema. An adapter serves it only when it
	// lists FEATURE_HOLDER_SIGN_IN_SOURCE.
	SetHolderSignInSource(context.Context, *connect.Request[v1.SetHolderSignInSourceRequest]) (*connect.Response[v1.SetHolderSignInSourceResponse], error)
	// ListConnections returns the DIDComm connections of the issuer. An
	// offer of CHANNEL_DIDCOMM_OOB can go to a wallet that connected
	// before. An adapter serves it only when it lists
	// PROTOCOL_DIDCOMM_ISSUE_V2.
	ListConnections(context.Context, *connect.Request[v1.ListConnectionsRequest]) (*connect.Response[v1.ListConnectionsResponse], error)
}

