type HolderBackendServiceClient interface {
	// Register creates the wallet account for one citizen.
	Register(context.Context, *connect.Request[v1.RegisterRequest]) (*connect.Response[v1.RegisterResponse], error)
	// ListCredentials returns the credentials in one wallet.
	ListCredentials(context.Context, *connect.Request[v1.ListCredentialsRequest]) (*connect.Response[v1.ListCredentialsResponse], error)
	// AcceptOffer claims a credential offer into the wallet.
	AcceptOffer(context.Context, *connect.Request[v1.AcceptOfferRequest]) (*connect.Response[v1.AcceptOfferResponse], error)
	// Present answers an OID4VP request with credentials from the wallet.
	Present(context.Context, *connect.Request[v1.PresentRequest]) (*connect.Response[v1.PresentResponse], error)
	// DeleteCredential removes one credential from the wallet.
	DeleteCredential(context.Context, *connect.Request[v1.DeleteCredentialRequest]) (*connect.Response[v1.DeleteCredentialResponse], error)
	// ListKeys lists the keys of a wallet. An adapter serves it when it
	// lists FEATURE_WALLET_KEYS.
	ListKeys(context.Context, *connect.Request[v1.ListKeysRequest]) (*connect.Response[v1.ListKeysResponse], error)
	// CreateKey makes a key in a wallet, of one of wallet_key_types.
	CreateKey(context.Context, *connect.Request[v1.CreateKeyRequest]) (*connect.Response[v1.CreateKeyResponse], error)
	// ListDids lists the DIDs of a wallet. An adapter serves it when it
	// lists FEATURE_WALLET_DIDS.
	ListDids(context.Context, *connect.Request[v1.ListDidsRequest]) (*connect.Response[v1.ListDidsResponse], error)
	// CreateDid makes a DID in a wallet, of one of wallet_did_methods.
	CreateDid(context.Context, *connect.Request[v1.CreateDidRequest]) (*connect.Response[v1.CreateDidResponse], error)
	// SetDefaultDid picks the DID a wallet binds new credentials to.
	SetDefaultDid(context.Context, *connect.Request[v1.SetDefaultDidRequest]) (*connect.Response[v1.SetDefaultDidResponse], error)
	// RejectOffer declines a credential offer in the wallet. An adapter
	// serves it when it lists FEATURE_WALLET_REJECT_OFFER.
	RejectOffer(context.Context, *connect.Request[v1.RejectOfferRequest]) (*connect.Response[v1.RejectOfferResponse], error)
	// ListEvents lists the event log of a wallet, newest first. An adapter
	// serves it when it lists FEATURE_WALLET_EVENTS.
	ListEvents(context.Context, *connect.Request[v1.ListEventsRequest]) (*connect.Response[v1.ListEventsResponse], error)
	// GetCredentialDocument returns a printable document of one held
	// credential, such as a PDF. An adapter serves it when it lists
	// FEATURE_WALLET_DOCUMENT.
	GetCredentialDocument(context.Context, *connect.Request[v1.GetCredentialDocumentRequest]) (*connect.Response[v1.GetCredentialDocumentResponse], error)
	// GetWalletLock reports whether the wallet needs the PIN of the
	// holder. An adapter serves it when it lists FEATURE_WALLET_PIN.
	GetWalletLock(context.Context, *connect.Request[v1.GetWalletLockRequest]) (*connect.Response[v1.GetWalletLockResponse], error)
	// UnlockWallet opens the wallet with the PIN the holder enters. It
	// makes the wallet with that PIN when the holder has none. The adapter
	// never stores the PIN.
	UnlockWallet(context.Context, *connect.Request[v1.UnlockWalletRequest]) (*connect.Response[v1.UnlockWalletResponse], error)
	// OpenInvitation opens a DIDComm invitation that carries no offer and
	// no proof request. The wallet keeps the connection (ADR-062). An
	// adapter serves it when it lists FEATURE_WALLET_DIDCOMM.
	OpenInvitation(context.Context, *connect.Request[v1.OpenInvitationRequest]) (*connect.Response[v1.OpenInvitationResponse], error)
	// ListWalletConnections returns the DIDComm connections of a wallet,
	// newest first. An adapter serves it when it lists
	// FEATURE_WALLET_DIDCOMM.
	ListWalletConnections(context.Context, *connect.Request[v1.ListWalletConnectionsRequest]) (*connect.Response[v1.ListWalletConnectionsResponse], error)
	// ListInbox returns the credential offers and the proof requests that
	// wait for the holder, newest first. Each came to the wallet over a
	// connection. An adapter serves it when it lists FEATURE_WALLET_DIDCOMM.
	ListInbox(context.Context, *connect.Request[v1.ListInboxRequest]) (*connect.Response[v1.ListInboxResponse], error)
}

